def slugify(text):
    return text.lower().strip().replace(' ', '-').replace('&', 'and').replace('/', '-').replace('(', '').replace(')', '')

def generate_catalogue():
    all_products = []
    flat_csv_rows = []

    for cat in CATEGORIES_DATA:
        cat_name = cat["name"]
        cat_slug = cat["slug"]
        for p in cat["items"]:
            pid, name, subcat, desc, brand, base_unit, mrp, selling, variants_raw, is_feat, is_best, img_url, keywords = p

            discount_pct = round(((mrp - selling) / mrp) * 100) if mrp > selling else 0

            # Build variants array
            variants = []
            for idx, v in enumerate(variants_raw):
                v_size, v_unit, v_mrp, v_sell = v
                v_disc = round(((v_mrp - v_sell) / v_mrp) * 100) if v_mrp > v_sell else 0
                variants.append({
                    "size": v_size,
                    "unit": v_unit,
                    "mrp": v_mrp,
                    "sellingPrice": v_sell,
                    "discountPercent": v_disc,
                    "stock": 100,
                    "sku": f"{pid}-{v_size.replace(' ', '')}",
                    "isDefault": (idx == 0)
                })

            prompt = f"Professional 1:1 e-commerce product photograph of {name}, Indian retail grocery packaging on clean pure white background, studio soft lighting, centered, sharp focus, 4k."

            product_obj = {
                "productId": pid,
                "name": name,
                "slug": slugify(name),
                "category": cat_name,
                "categorySlug": cat_slug,
                "subcategory": subcat,
                "description": desc,
                "brand": brand,
                "unit": variants[0]["size"] if variants else f"1 {base_unit}",
                "mrp": mrp,
                "price": mrp,
                "sellingPrice": selling,
                "discountPrice": selling if selling < mrp else 0,
                "discountPercent": discount_pct,
                "stock": 120,
                "isVeg": True,
                "type": "grocery",
                "images": [img_url],
                "imagePrompt": prompt,
                "isFeatured": is_feat,
                "isBestseller": is_best,
                "rating": {"average": 4.6 if is_best else 4.4, "count": 84 if is_best else 36},
                "variants": variants,
                "keywords": keywords,
                "isActive": True
            }
            all_products.append(product_obj)

            # CSV flat row
            flat_csv_rows.append({
                "Product ID": pid,
                "Product Name": name,
                "Brand": brand,
                "Category": cat_name,
                "Subcategory": subcat,
                "Description": desc,
                "Default Size": variants[0]["size"] if variants else f"1 {base_unit}",
                "MRP (INR)": mrp,
                "Selling Price (INR)": selling,
                "Discount %": discount_pct,
                "Stock": 120,
                "Featured": "Yes" if is_feat else "No",
                "Bestseller": "Yes" if is_best else "No",
                "Dietary": "Vegetarian",
                "Image URL": img_url,
                "Pack Variants Available": " | ".join([f"{v['size']}: ₹{v['sellingPrice']} (MRP ₹{v['mrp']})" for v in variants]),
                "Search Keywords": ", ".join(keywords),
                "AI Image Prompt": prompt
            })

    # Save JSON
    with open("cravecourier_grocery_catalogue.json", "w", encoding="utf-8") as f:
        json.dump(all_products, f, indent=2, ensure_ascii=False)

    # Save CSV
    fieldnames = [
        "Product ID", "Product Name", "Brand", "Category", "Subcategory",
        "Description", "Default Size", "MRP (INR)", "Selling Price (INR)",
        "Discount %", "Stock", "Featured", "Bestseller", "Dietary",
        "Image URL", "Pack Variants Available", "Search Keywords", "AI Image Prompt"
    ]
    with open("cravecourier_grocery_catalogue.csv", "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(flat_csv_rows)

    print(f"[OK] Generated {len(all_products)} products across {len(CATEGORIES_DATA)} categories.")
    print("Files written: cravecourier_grocery_catalogue.json, cravecourier_grocery_catalogue.csv")

if __name__ == "__main__":
    generate_catalogue()
